export type IconName = keyof typeof PATHS;

export function Icon({
  name,
  className,
  solid,
}: {
  name: IconName;
  className?: string;
  solid?: boolean;
}) {
  return (
    <svg
      className={className ? `icon ${className}` : 'icon'}
      viewBox="0 0 24 24"
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
    >
      <path d={PATHS[name][solid ? 'filled' : 'regular']} />
    </svg>
  );
}
